"use client";

/**
 * AIDocumentGenerator.tsx
 * ---------------------------------------------------------------------------
 * Production-ready AI document generator for CTU (or any institution/brand).
 *
 * Generates ANY kind of document (academic, business, legal, invoices,
 * contracts, reports, proposals, letters, NDAs, certificates, etc.) from a
 * natural-language prompt, with optional user-supplied header/footer images
 * (letterhead) that are NEVER touched or generated by the AI. Exports to
 * DOCX (primary) and PDF (secondary).
 *
 * REQUIRED NPM PACKAGES
 * ---------------------------------------------------------------------------
 *   npm install docx file-saver jspdf lucide-react
 *   npm install -D @types/file-saver
 *
 * - docx        -> builds real .docx files (headers/footers/images/styles)
 * - file-saver  -> triggers the browser "Save As" download
 * - jspdf       -> builds the .pdf export (text-based, so it stays small,
 *                  selectable, and doesn't require rendering the DOM to a
 *                  canvas like the html2canvas approach would)
 * - lucide-react -> icons
 *
 * WHY jsPDF INSTEAD OF pdf-lib / html2canvas
 * ---------------------------------------------------------------------------
 * pdf-lib has no built-in text-wrapping/layout engine, and html2canvas
 * rasterizes the page (blurry text, huge file size, no selectable text).
 * jsPDF gives us simple, reliable text flow + image placement, which is all
 * a generated document needs, and keeps output crisp and searchable.
 *
 * CONNECTING A REAL AI API (Groq / OpenAI-compatible)
 * ---------------------------------------------------------------------------
 * 1. Create app/api/generate-document/route.ts (see the fully-commented
 *    example at the bottom of this file).
 * 2. Set your API key as a server-only env var, e.g. GROQ_API_KEY or
 *    OPENAI_API_KEY, in .env.local. Never expose it to the client.
 * 3. In this component, uncomment the `callRealAI` implementation inside
 *    `handleGenerate` and delete/comment out the mock generator.
 * 4. The API route should ONLY ever return body content. It must never be
 *    asked to design or generate a header/footer image or letterhead -
 *    that responsibility stays entirely client-side (see SYSTEM_PROMPT).
 */

