/* ============================================================================
 * SHARED TYPES
 * ==========================================================================*/
type ImageAsset = {
  dataUrl: string; // base64 data URL, used for on-screen preview + PDF
  base64: string; // raw base64 (no prefix), used for docx ImageRun
  mimeType: "png" | "jpg" | "gif" | "bmp";
  width: number;
  height: number;
  fileName: string;
};

type GenerationStatus = "idle" | "generating" | "success" | "error";
type DownloadTarget = "docx" | "pdf" | null;

/* ============================================================================
 * IMAGE CONSTRAINTS
 * Keeps headers/footers looking professional and file sizes sane.
 * ==========================================================================*/
const MAX_IMAGE_DIMENSION_PX = 1600; // downscale ceiling
const MAX_IMAGE_SIZE_MB = 5;
const HEADER_FOOTER_DISPLAY_HEIGHT_PX = 70; // on-page target height in docx (px @96dpi)

const ACCEPTED_IMAGE_TYPES = ["image/png", "image/jpeg", "image/webp"];

/* ============================================================================
 * UTILITIES
 * ==========================================================================*/

/** Reads a File into a downsized base64 PNG/JPEG (via canvas), returning both
 *  a full data URL (for <img> previews) and the raw base64 payload (for
 *  docx's ImageRun, which wants bytes, not a data URL). */
async function fileToImageAsset(file: File): Promise<ImageAsset> {
  if (!ACCEPTED_IMAGE_TYPES.includes(file.type)) {
    throw new Error("Please upload a PNG, JPG, or WEBP image.");
  }
  if (file.size > MAX_IMAGE_SIZE_MB * 1024 * 1024) {
    throw new Error(`Image must be smaller than ${MAX_IMAGE_SIZE_MB}MB.`);
  }

  const rawDataUrl: string = await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = () => reject(new Error("Could not read the image file."));
    reader.readAsDataURL(file);
  });

  const img = await new Promise<HTMLImageElement>((resolve, reject) => {
    const el = new window.Image();
    el.onload = () => resolve(el);
    el.onerror = () => reject(new Error("Could not decode the image file."));
    el.src = rawDataUrl;
  });

  // Downscale to keep the exported document a reasonable size.
  let { width, height } = img;
  if (width > MAX_IMAGE_DIMENSION_PX || height > MAX_IMAGE_DIMENSION_PX) {
    const scale = MAX_IMAGE_DIMENSION_PX / Math.max(width, height);
    width = Math.round(width * scale);
    height = Math.round(height * scale);
  }

  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Canvas is not supported in this browser.");
  ctx.drawImage(img, 0, 0, width, height);

  // Always normalize to PNG so docx's ImageRun type stays predictable and
  // transparency (common in letterhead logos) is preserved.
  const dataUrl = canvas.toDataURL("image/png");
  const base64 = dataUrl.split(",")[1];

  return {
    dataUrl,
    base64,
    mimeType: "png",
    width,
    height,
    fileName: file.name,
  };
}

/** Converts a base64 PNG string into a Uint8Array for docx's ImageRun. */
function base64ToUint8Array(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

/** Very small markdown-ish parser: turns the AI's plain-text output into a
 *  list of typed blocks the DOCX/PDF builders can render consistently. */
type ContentBlock =
  | { type: "h1"; text: string }
  | { type: "h2"; text: string }
  | { type: "h3"; text: string }
  | { type: "bullet"; text: string }
  | { type: "paragraph"; text: string };

function parseContentToBlocks(raw: string): ContentBlock[] {
  const lines = raw.replace(/\r\n/g, "\n").split("\n");
  const blocks: ContentBlock[] = [];

  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line) continue;

    if (line.startsWith("### ")) {
      blocks.push({ type: "h3", text: line.slice(4).trim() });
    } else if (line.startsWith("## ")) {
      blocks.push({ type: "h2", text: line.slice(3).trim() });
    } else if (line.startsWith("# ")) {
      blocks.push({ type: "h1", text: line.slice(2).trim() });
    } else if (line.startsWith("- ") || line.startsWith("* ")) {
      blocks.push({ type: "bullet", text: line.slice(2).trim() });
    } else if (/^-{3,}$/.test(line)) {
      // horizontal rule markers from the mock generator - skip cleanly
      continue;
    } else {
      blocks.push({ type: "paragraph", text: line });
    }
  }
  return blocks;
}

function sanitizeFileNameSegment(input: string): string {
  return input
    .trim()
    .slice(0, 40)
    .replace(/[^a-z0-9\s-]/gi, "")
    .replace(/\s+/g, "_");
}

function buildFileBaseName(prompt: string): string {
  const today = new Date().toISOString().slice(0, 10); // YYYY-MM-DD
  const slug = sanitizeFileNameSegment(prompt) || "Document";
  return `${slug}_${today}`;
}

