/* ============================================================================
 * MAIN COMPONENT
 * ==========================================================================*/
export function DocumentGenerator() {
  const [prompt, setPrompt] = useState("");
  const [generatedContent, setGeneratedContent] = useState("");
  const [status, setStatus] = useState<GenerationStatus>("idle");
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [downloading, setDownloading] = useState<DownloadTarget>(null);
  const [copySuccess, setCopySuccess] = useState(false);
  const [showAllPrompts, setShowAllPrompts] = useState(false);

  // Header state
  const [headerImage, setHeaderImage] = useState<ImageAsset | null>(null);
  const [noHeader, setNoHeader] = useState(true);
  const [headerError, setHeaderError] = useState<string | null>(null);

  // Footer state
  const [footerImage, setFooterImage] = useState<ImageAsset | null>(null);
  const [noFooter, setNoFooter] = useState(true);
  const [footerError, setFooterError] = useState<string | null>(null);

  const headerInputRef = useRef<HTMLInputElement>(null);
  const footerInputRef = useRef<HTMLInputElement>(null);

  const visiblePrompts = useMemo(
    () => (showAllPrompts ? QUICK_PROMPTS : QUICK_PROMPTS.slice(0, COLLAPSED_PROMPT_COUNT)),
    [showAllPrompts]
  );

  /* ---------------------------------------------------------------------- */
  /* Image upload handlers                                                   */
  /* ---------------------------------------------------------------------- */
  const handleHeaderUpload = async (file: File | undefined) => {
    if (!file) return;
    setHeaderError(null);
    try {
      const asset = await fileToImageAsset(file);
      setHeaderImage(asset);
      setNoHeader(false);
    } catch (err) {
      setHeaderError(err instanceof Error ? err.message : "Could not process image.");
    } finally {
      if (headerInputRef.current) headerInputRef.current.value = "";
    }
  };

  const handleFooterUpload = async (file: File | undefined) => {
    if (!file) return;
    setFooterError(null);
    try {
      const asset = await fileToImageAsset(file);
      setFooterImage(asset);
      setNoFooter(false);
    } catch (err) {
      setFooterError(err instanceof Error ? err.message : "Could not process image.");
    } finally {
      if (footerInputRef.current) footerInputRef.current.value = "";
    }
  };

  const removeHeaderImage = () => {
    setHeaderImage(null);
    setHeaderError(null);
  };

  const removeFooterImage = () => {
    setFooterImage(null);
    setFooterError(null);
  };

  /* ---------------------------------------------------------------------- */
  /* Generation                                                               */
  /* ---------------------------------------------------------------------- */
  const handleGenerate = async () => {
    if (!prompt.trim()) return;

    setStatus("generating");
    setErrorMessage(null);

    try {
      // --- LIVE AI CALL via /api/generate-document (OpenAI) ----------------
      const content = await callRealAI(prompt);

      // --- MOCK (no backend required) — switch back to this for offline dev:
      // const content = await mockGenerateDocument(prompt);

      setGeneratedContent(content);
      setStatus("success");
    } catch (err) {
      setErrorMessage(
        err instanceof Error ? err.message : "Something went wrong while generating your document."
      );
      setStatus("error");
    }
  };

  /** Calls our own Next.js API route, which in turn calls OpenAI server-side.
   *  Keeping the API key out of the browser is why this two-hop setup exists:
   *  the component never talks to OpenAI directly. */
  async function callRealAI(userPrompt: string): Promise<string> {
    const response = await fetch("/api/generate-document", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ prompt: userPrompt }),
    });
    if (!response.ok) {
      const body = await response.json().catch(() => null);
      throw new Error(body?.error ?? "The AI service could not generate this document.");
    }
    const data = await response.json();
    return data.content as string;
  }

  /* ---------------------------------------------------------------------- */
  /* Copy                                                                     */
  /* ---------------------------------------------------------------------- */
  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(generatedContent);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    } catch {
      setErrorMessage("Could not copy to clipboard. Please copy the text manually.");
    }
  };

  /* ---------------------------------------------------------------------- */
  /* DOCX export                                                              */
  /* ---------------------------------------------------------------------- */
  const handleDownloadDocx = async () => {
    if (!generatedContent.trim()) return;
    setDownloading("docx");
    setErrorMessage(null);

    try {
      const blocks = parseContentToBlocks(generatedContent);

      const bodyParagraphs = blocks.map((block) => {
        switch (block.type) {
          case "h1":
            return new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 120, after: 280 },
              children: [
                new TextRun({
                  text: block.text.toUpperCase(),
                  bold: true,
                  size: 32, // 16pt
                }),
              ],
            });
          case "h2":
            return new Paragraph({
              spacing: { before: 260, after: 140 },
              children: [
                new TextRun({
                  text: block.text,
                  bold: true,
                  underline: {},
                  size: 24, // 12pt
                }),
              ],
            });
          case "h3":
            return new Paragraph({
              spacing: { before: 200, after: 110 },
              children: [
                new TextRun({
                  text: block.text,
                  bold: true,
                  underline: {},
                  size: 22, // 11pt
                }),
              ],
            });
          case "bullet":
            return new Paragraph({
              text: block.text,
              bullet: { level: 0 },
              spacing: { after: 80 },
            });
          case "paragraph":
          default:
            return new Paragraph({
              children: [new TextRun(block.text)],
              spacing: { after: 120 },
              alignment: AlignmentType.LEFT,
            });
        }
      });

      // Header: user-uploaded image only, centered. AI never writes this.
      const headerContent =
        !noHeader && headerImage
          ? new Header({
              children: [
                new Paragraph({
                  alignment: AlignmentType.CENTER,
                  children: [
                    new ImageRun({
                      data: base64ToUint8Array(headerImage.base64),
                      transformation: scaledDocxDimensions(headerImage),
                      type: "png",
                    }),
                  ],
                }),
              ],
            })
          : new Header({ children: [new Paragraph("")] });

      // Footer: same rule - user image only, or blank.
      const footerContent =
        !noFooter && footerImage
          ? new Footer({
              children: [
                new Paragraph({
                  alignment: AlignmentType.CENTER,
                  children: [
                    new ImageRun({
                      data: base64ToUint8Array(footerImage.base64),
                      transformation: scaledDocxDimensions(footerImage),
                      type: "png",
                    }),
                  ],
                }),
              ],
            })
          : new Footer({ children: [new Paragraph("")] });

      const doc = new Document({
        sections: [
          {
            properties: {
              page: {
                margin: { top: 1440, bottom: 1440, left: 1440, right: 1440 },
              },
            },
            headers: { default: headerContent },
            footers: { default: footerContent },
            children: bodyParagraphs,
          },
        ],
        styles: {
          default: {
            document: {
              run: { font: "Calibri", size: 22 }, // 11pt
            },
          },
        },
      });

      const blob = await Packer.toBlob(doc);
      saveAs(blob, `${buildFileBaseName(prompt)}.docx`);
    } catch (err) {
      setErrorMessage(
        err instanceof Error ? err.message : "Could not generate the DOCX file. Please try again."
      );
    } finally {
      setDownloading(null);
    }
  };

  /* ---------------------------------------------------------------------- */
  /* PDF export                                                               */
  /* ---------------------------------------------------------------------- */
  const handleDownloadPdf = async () => {
    if (!generatedContent.trim()) return;
    setDownloading("pdf");
    setErrorMessage(null);

    try {
      const doc = new jsPDF({ unit: "pt", format: "letter" }); // 612 x 792 pt
      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      const marginX = 56; // ~0.78in
      const contentWidth = pageWidth - marginX * 2;

      const headerReservedHeight = !noHeader && headerImage ? 70 : 0;
      const footerReservedHeight = !noFooter && footerImage ? 60 : 0;
      const topMargin = 50 + headerReservedHeight;
      const bottomMargin = 50 + footerReservedHeight;

      let cursorY = topMargin;

      const drawHeaderFooterOnPage = () => {
        if (!noHeader && headerImage) {
          const { width, height } = fitDimensions(headerImage, contentWidth, 60);
          const x = marginX + (contentWidth - width) / 2;
          doc.addImage(headerImage.dataUrl, "PNG", x, 24, width, height);
        }
        if (!noFooter && footerImage) {
          const { width, height } = fitDimensions(footerImage, contentWidth, 50);
          const x = marginX + (contentWidth - width) / 2;
          doc.addImage(footerImage.dataUrl, "PNG", x, pageHeight - bottomMargin + 10, width, height);
        }
      };

      const ensureSpace = (neededHeight: number) => {
        if (cursorY + neededHeight > pageHeight - bottomMargin) {
          drawHeaderFooterOnPage();
          doc.addPage();
          cursorY = topMargin;
        }
      };

      const blocks = parseContentToBlocks(generatedContent);

      for (const block of blocks) {
        let fontSize = 11;
        let fontStyle: "normal" | "bold" = "normal";
        let prefix = "";
        let extraSpacingBefore = 6;
        let lineHeight = 15;

        if (block.type === "h1") {
          fontSize = 18;
          fontStyle = "bold";
          extraSpacingBefore = 18;
          lineHeight = 22;
        } else if (block.type === "h2") {
          fontSize = 14;
          fontStyle = "bold";
          extraSpacingBefore = 14;
          lineHeight = 18;
        } else if (block.type === "h3") {
          fontSize = 12.5;
          fontStyle = "bold";
          extraSpacingBefore = 10;
          lineHeight = 16;
        } else if (block.type === "bullet") {
          prefix = "•  ";
        }

        doc.setFont("helvetica", fontStyle);
        doc.setFontSize(fontSize);

        const displayText = block.type === "h1" ? block.text.toUpperCase() : block.text;
        const text = prefix + displayText;
        const wrapWidth = block.type === "bullet" ? contentWidth - 14 : contentWidth;
        const lines: string[] = doc.splitTextToSize(text, wrapWidth);

        cursorY += extraSpacingBefore;
        ensureSpace(lines.length * lineHeight);

        const isUnderlinedHeading = block.type === "h2" || block.type === "h3";

        for (const line of lines) {
          ensureSpace(lineHeight);

          let xPos = marginX;
          if (block.type === "h1") {
            const lineWidth = doc.getTextWidth(line);
            xPos = marginX + (contentWidth - lineWidth) / 2;
          } else if (block.type === "bullet" && line !== lines[0]) {
            xPos = marginX + 14;
          }

          doc.text(line, xPos, cursorY);

          if (isUnderlinedHeading) {
            const lineWidth = doc.getTextWidth(line);
            doc.setLineWidth(0.75);
            doc.line(xPos, cursorY + 2, xPos + lineWidth, cursorY + 2);
          }

          cursorY += lineHeight;
        }
      }

      // Draw header/footer on the final page too.
      drawHeaderFooterOnPage();

      // Backfill header/footer on every earlier page (addImage above only
      // draws on the page active at that time, so re-walk all pages once).
      const pageCount = doc.getNumberOfPages();
      for (let i = 1; i <= pageCount; i++) {
        doc.setPage(i);
        if (!noHeader && headerImage) {
          const { width, height } = fitDimensions(headerImage, contentWidth, 60);
          const x = marginX + (contentWidth - width) / 2;
          doc.addImage(headerImage.dataUrl, "PNG", x, 24, width, height);
        }
        if (!noFooter && footerImage) {
          const { width, height } = fitDimensions(footerImage, contentWidth, 50);
          const x = marginX + (contentWidth - width) / 2;
          doc.addImage(footerImage.dataUrl, "PNG", x, pageHeight - bottomMargin + 10, width, height);
        }
      }

      doc.save(`${buildFileBaseName(prompt)}.pdf`);
    } catch (err) {
      setErrorMessage(
        err instanceof Error ? err.message : "Could not generate the PDF file. Please try again."
      );
    } finally {
      setDownloading(null);
    }
  };

  /* ---------------------------------------------------------------------- */
  /* Render                                                                   */
  /* ---------------------------------------------------------------------- */
  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div>
          <div className="flex items-center gap-2 mb-2">
            <Sparkles className="h-8 w-8" style={{ color: BRAND.yellow }} />
            <h1 className="text-3xl text-gray-900">AI Document Generator</h1>
          </div>
          <p className="text-gray-600">
            Generate any document — academic, business, or legal — using AI-powered assistance.
          </p>
        </div>
      </div>

      {/* Global error banner */}
      {errorMessage && (
        <div className="flex items-start gap-3 p-4 bg-red-50 border-l-4 rounded" style={{ borderColor: BRAND.red }}>
          <AlertCircle className="h-5 w-5 mt-0.5 flex-shrink-0" style={{ color: BRAND.red }} />
          <p className="text-sm text-gray-700">{errorMessage}</p>
        </div>
      )}

      {/* Prompt Section */}
      <div className="bg-white rounded-lg shadow-md p-6">
        <h2 className="text-xl mb-4" style={{ color: BRAND.red }}>
          Describe Your Document
        </h2>
        <div className="space-y-4">
          <div>
            <label className="block text-sm mb-2 text-gray-700">What would you like to generate?</label>
            <textarea
              value={prompt}
              onChange={(e) => setPrompt(e.target.value)}
              rows={6}
              className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 transition-shadow"
              style={{ backgroundColor: BRAND.bg, ["--tw-ring-color" as string]: BRAND.yellow }}
              placeholder="Describe the document you want to generate. Be as specific as possible — document type, subject/purpose, audience, key sections, and any specific requirements..."
            />
          </div>

          {/* Header upload */}
          <ImageUploadField
            label="Header Image (Letterhead)"
            helperText="Shown centered at the top of every page. The AI never writes header content — only your uploaded image appears here."
            noneLabel="No Header"
            noneChecked={noHeader}
            onNoneChange={(checked) => {
              setNoHeader(checked);
              if (checked) removeHeaderImage();
            }}
            image={headerImage}
            error={headerError}
            inputRef={headerInputRef}
            onFileSelected={handleHeaderUpload}
            onRemove={removeHeaderImage}
          />

          {/* Footer upload */}
          <ImageUploadField
            label="Footer Image"
            helperText="Shown centered at the bottom of every page. The AI never writes footer content — only your uploaded image appears here."
            noneLabel="No Footer"
            noneChecked={noFooter}
            onNoneChange={(checked) => {
              setNoFooter(checked);
              if (checked) removeFooterImage();
            }}
            image={footerImage}
            error={footerError}
            inputRef={footerInputRef}
            onFileSelected={handleFooterUpload}
            onRemove={removeFooterImage}
          />

          <button
            onClick={handleGenerate}
            disabled={status === "generating" || !prompt.trim()}
            className="w-full flex items-center justify-center gap-2 px-6 py-3 text-white rounded-lg transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            style={{ backgroundColor: BRAND.red }}
            onMouseEnter={(e) => {
              if (status !== "generating") (e.currentTarget as HTMLButtonElement).style.backgroundColor = BRAND.redHover;
            }}
            onMouseLeave={(e) => {
              (e.currentTarget as HTMLButtonElement).style.backgroundColor = BRAND.red;
            }}
          >
            {status === "generating" ? (
              <>
                <RefreshCw className="h-5 w-5 animate-spin" />
                Generating with AI...
              </>
            ) : (
              <>
                <Sparkles className="h-5 w-5" />
                Generate with AI
              </>
            )}
          </button>
        </div>
      </div>

      {/* Quick Prompts */}
      <div className="bg-white rounded-lg shadow-md p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-xl" style={{ color: BRAND.red }}>
            Quick Prompts
          </h2>
          <button
            onClick={() => setShowAllPrompts((v) => !v)}
            className="flex items-center gap-1 text-sm text-gray-600 hover:text-gray-900 transition-colors"
          >
            {showAllPrompts ? (
              <>
                Show less <ChevronUp className="h-4 w-4" />
              </>
            ) : (
              <>
                Show all ({QUICK_PROMPTS.length}) <ChevronDown className="h-4 w-4" />
              </>
            )}
          </button>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
          {visiblePrompts.map((quickPrompt, index) => (
            <button
              key={index}
              onClick={() => setPrompt(quickPrompt)}
              className="w-full text-left p-4 rounded-lg border-2 border-transparent transition-all hover:border-current"
              style={{ backgroundColor: BRAND.bg }}
              onMouseEnter={(e) => {
                (e.currentTarget as HTMLButtonElement).style.backgroundColor = `${BRAND.yellow}1A`;
                (e.currentTarget as HTMLButtonElement).style.borderColor = BRAND.yellow;
              }}
              onMouseLeave={(e) => {
                (e.currentTarget as HTMLButtonElement).style.backgroundColor = BRAND.bg;
                (e.currentTarget as HTMLButtonElement).style.borderColor = "transparent";
              }}
            >
              <p className="text-gray-700 text-sm">{quickPrompt}</p>
            </button>
          ))}
        </div>
      </div>

      {/* Generated Content */}
      {status !== "idle" && (status === "generating" || generatedContent) && (
        <div className="bg-white rounded-lg shadow-md p-6">
          <div className="flex items-center justify-between mb-4 flex-wrap gap-3">
            <h2 className="text-xl" style={{ color: BRAND.red }}>
              Generated Content
            </h2>

            {generatedContent && status !== "generating" && (
              <div className="flex gap-2 flex-wrap">
                <button
                  onClick={handleCopy}
                  className="flex items-center gap-2 px-4 py-2 rounded-lg border transition-colors"
                  style={{ color: BRAND.green, borderColor: BRAND.green }}
                >
                  {copySuccess ? <CheckCircle2 className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
                  {copySuccess ? "Copied!" : "Copy"}
                </button>
                <button
                  onClick={handleDownloadDocx}
                  disabled={downloading !== null}
                  className="flex items-center gap-2 px-4 py-2 text-white rounded-lg transition-colors disabled:opacity-50"
                  style={{ backgroundColor: BRAND.green }}
                >
                  {downloading === "docx" ? (
                    <RefreshCw className="h-4 w-4 animate-spin" />
                  ) : (
                    <FileText className="h-4 w-4" />
                  )}
                  Download DOCX
                </button>
                <button
                  onClick={handleDownloadPdf}
                  disabled={downloading !== null}
                  className="flex items-center gap-2 px-4 py-2 text-gray-900 rounded-lg transition-colors disabled:opacity-50"
                  style={{ backgroundColor: BRAND.yellow }}
                >
                  {downloading === "pdf" ? (
                    <RefreshCw className="h-4 w-4 animate-spin" />
                  ) : (
                    <FileDown className="h-4 w-4" />
                  )}
                  Download PDF
                </button>
              </div>
            )}
          </div>

          {status === "generating" ? (
            <div className="p-10 flex flex-col items-center justify-center gap-3 rounded-lg border border-gray-300" style={{ backgroundColor: BRAND.bg }}>
              <RefreshCw className="h-8 w-8 animate-spin" style={{ color: BRAND.red }} />
              <p className="text-sm text-gray-600">Drafting your document...</p>
            </div>
          ) : (
            <>
              <label className="block text-sm mb-2 text-gray-700">
                Edit the content below before downloading
              </label>
              <textarea
                value={generatedContent}
                onChange={(e) => setGeneratedContent(e.target.value)}
                rows={18}
                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 font-mono text-sm leading-relaxed text-gray-700"
                style={{ backgroundColor: BRAND.bg, ["--tw-ring-color" as string]: BRAND.yellow }}
              />

              <div
                className="mt-4 p-4 border-l-4 rounded"
                style={{ backgroundColor: `${BRAND.yellow}1A`, borderColor: BRAND.yellow }}
              >
                <p className="text-sm text-gray-700">
                  <strong>Note:</strong> This is AI-generated content. Please review and edit as needed
                  before exporting. Header and footer images (if provided) are inserted exactly as
                  uploaded and are never modified by the AI.
                </p>
              </div>
            </>
          )}
        </div>
      )}
    </div>
  );
}

/* ============================================================================
 * SUBCOMPONENT: Header / Footer image upload field
 * ==========================================================================*/
function ImageUploadField(props: {
  label: string;
  helperText: string;
  noneLabel: string;
  noneChecked: boolean;
  onNoneChange: (checked: boolean) => void;
  image: ImageAsset | null;
  error: string | null;
  inputRef: RefObject<HTMLInputElement | null>;
  onFileSelected: (file: File | undefined) => void;
  onRemove: () => void;
}) {
  const {
    label,
    helperText,
    noneLabel,
    noneChecked,
    onNoneChange,
    image,
    error,
    inputRef,
    onFileSelected,
    onRemove,
  } = props;

  return (
    <div className="border border-gray-200 rounded-lg p-4" style={{ backgroundColor: "#FAFAFA" }}>
      <div className="flex items-center justify-between flex-wrap gap-2 mb-2">
        <span className="text-sm text-gray-700 font-medium">{label}</span>
        <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer select-none">
          <input
            type="checkbox"
            checked={noneChecked}
            onChange={(e) => onNoneChange(e.target.checked)}
            className="h-4 w-4 rounded border-gray-300"
            style={{ accentColor: BRAND.red }}
          />
          {noneLabel}
        </label>
      </div>
      <p className="text-xs text-gray-500 mb-3">{helperText}</p>

      {error && <p className="text-xs mb-2" style={{ color: BRAND.red }}>{error}</p>}

      {!noneChecked && (
        <>
          {!image ? (
            <button
              type="button"
              onClick={() => inputRef.current?.click()}
              className="w-full flex flex-col items-center justify-center gap-2 py-6 border-2 border-dashed rounded-lg text-gray-500 hover:text-gray-700 transition-colors"
              style={{ borderColor: "#D1D5DB" }}
            >
              <ImageIcon className="h-6 w-6" />
              <span className="text-sm">Click to upload PNG, JPG, or WEBP</span>
            </button>
          ) : (
            <div className="relative inline-block">
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={image.dataUrl}
                alt={`${label} preview`}
                className="max-h-24 rounded border border-gray-300 bg-white p-1"
              />
              <button
                type="button"
                onClick={onRemove}
                aria-label={`Remove ${label.toLowerCase()}`}
                className="absolute -top-2 -right-2 h-6 w-6 flex items-center justify-center rounded-full text-white shadow"
                style={{ backgroundColor: BRAND.red }}
              >
                <X className="h-4 w-4" />
              </button>
            </div>
          )}
          <input
            ref={inputRef}
            type="file"
            accept={ACCEPTED_IMAGE_TYPES.join(",")}
            className="hidden"
            onChange={(e) => onFileSelected(e.target.files?.[0])}
          />
        </>
      )}
    </div>
  );
}

/* ============================================================================
 * DOCX image scaling helper
 * Keeps the aspect ratio and caps the on-page height so header/footer images
 * never dominate the page.
 * ==========================================================================*/
function scaledDocxDimensions(image: ImageAsset): { width: number; height: number } {
  const maxHeight = HEADER_FOOTER_DISPLAY_HEIGHT_PX;
  const aspect = image.width / image.height;
  const height = Math.min(maxHeight, image.height);
  const width = Math.round(height * aspect);
  return { width, height: Math.round(height) };
}

/** Fits an image within a max width/height box for the PDF renderer,
 *  preserving aspect ratio. */
function fitDimensions(
  image: ImageAsset,
  maxWidth: number,
  maxHeight: number
): { width: number; height: number } {
  const aspect = image.width / image.height;
  let width = maxWidth;
  let height = width / aspect;
  if (height > maxHeight) {
    height = maxHeight;
    width = height * aspect;
  }
  return { width, height };
}

